class Solution {
    int ans = 1;

    int dfs(int u, const vector<vector<int>>& children, const string& s) {
        int first = 0, second = 0;
        for (int v : children[u]) {
            int lenV = dfs(v, children, s);
            if (s[v] != s[u]) {
                if (lenV > first) {
                    second = first;
                    first = lenV;
                } else if (lenV > second) {
                    second = lenV;
                }
            }
        }
        ans = max(ans, 1 + first + second);
        return 1 + first;
    }

