class Solution {
    private int ans = 1;

    private int dfs(int u, List<List<Integer>> children, String s) {
        int first = 0, second = 0;
        for (int v : children.get(u)) {
            int lenV = dfs(v, children, s);
            if (s.charAt(v) != s.charAt(u)) {
                if (lenV > first) {
                    second = first;
                    first = lenV;
                } else if (lenV > second) {
                    second = lenV;
                }
            }
        }
        ans = Math.max(ans, 1 + first + second);
        return 1 + first;
    }

    public int longestPath(int[] parent, String s) {
        int n = parent.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; i++) children.add(new ArrayList<>());
        for (int i = 1; i < n; i++) {
            children.get(parent[i]).add(i);
        }
        dfs(0, children, s);
        return ans;
    }
}

