var longestPath = function(parent, s) {
    const n = parent.length;
    const children = Array.from({ length: n }, () => []);
    for (let i = 1; i < n; i++) {
        children[parent[i]].push(i);
    }
    let ans = 1;
    function dfs(u) {
        let first = 0, second = 0;
        for (const v of children[u]) {
            const lenV = dfs(v);
            if (s[v] !== s[u]) {
                if (lenV > first) {
                    second = first;
                    first = lenV;
                } else if (lenV > second) {
                    second = lenV;
                }
            }
        }
        ans = Math.max(ans, 1 + first + second);
        return 1 + first;
    }
    dfs(0);
    return ans;
};
